body:
As far as logs go, there are nothing abnormal and they only contain output from lambda code.

I know lambda finishes completely because I get its result returned with data from handler's return object. Below are two classes that show pretty much everything lambda is doing.

```
package hist.server;

import javax.inject.Inject;
import javax.inject.Named;

import com.amazonaws.services.lambda.runtime.Context;
import com.amazonaws.services.lambda.runtime.RequestHandler;

@Named("test")
public class TestLambda implements RequestHandler<InputObject, OutputObject> {

    @Inject
    ProcessingService service;

    @Override
    public OutputObject handleRequest(InputObject input, Context context) {
        return service.proces(input).setRequestId(context.getAwsRequestId());
    }
}

package hist.server;

import hist.server.domain.BlueskyCompliance;

import javax.enterprise.context.ApplicationScoped;
import javax.inject.Inject;
import javax.transaction.Transactional;
import java.util.Optional;

@ApplicationScoped
public class ProcessingService {
    @Inject
    BlueskyComplianceRepository repo;

    @Transactional
    public OutputObject proces(InputObject input) {
        System.out.println("In process");
        Optional<BlueskyCompliance> bs = repo.findById(1);

        String result = input.getGreeting() + " " + (bs.isPresent() ? bs.get().getState() : "No BS");
        OutputObject out = new OutputObject();
        out.setResult(result);
        return out;
    }
}
```
